sort(intervals.begin(), intervals.end());
priority_queue<int, vector<int>, greater<int>> active;
for (auto& it : intervals) {
    if (!active.empty() && active.top() <= it[0]) active.pop();
    active.push(it[1]);
}
return active.size();

