    events.push_back({it[0], 1});
    events.push_back({it[1], -1});
}
sort(events.begin(), events.end());       // -1 before +1 at a tie
int cur = 0, best = 0;
for (auto& [t, d] : events) { cur += d; best = max(best, cur); }
